"""Append verified camera-only context without rewriting historical experiments."""
import json,sys
from common import ROOT,OUT

def append(name,title,body):
 path=ROOT/name;text=path.read_text()
 if title in text:return
 with path.open('a') as f:f.write('\n\n## '+title+'\n\n'+body+'\n')

def run(audit_only=False):
 a=json.loads((OUT/'audit_decision.json').read_text());r1=a['robots']['robot1'];r3=a['robots']['robot3']
 if audit_only:
  append('EXPERIMENT_LOG.md','2026-11-10 — Complete RGB-D archive audit and full-run launch',f"Objective: replace the bounded pilot assumption with a complete camera-only input audit. All four RGB/depth archive DBs passed EOF CRC and metadata counts; every recorded calibration message was inspected and constant. Robot1: {r1['rgb_frames']} RGB / {r1['depth_frames']} depth clouds over {r1['duration_s']:.9f} s; Robot3: {r3['rgb_frames']} / {r3['depth_frames']} over {r3['duration_s']:.9f} s. Paired RGB fractions under the existing 25 ms bag-time gate are {r1['paired_fraction']:.6f} / {r3['paired_fraction']:.6f}; all paired original header differences are zero. Exact timestamps, frequencies, gaps, calibration and provenance: docs/CUMULTI_RGBD_FULL_DATA_AUDIT.md and outputs/cumulti_v1/24_rgbd_full_v1/.\n\nIndependent full original-rate 1000-feature native RGB-D tracking was launched from each recording's start, with no 120-second stop. Unknown depth stays zero; tracking and dense maps preserve independent reset gauges. At this checkpoint full tracking/rendering/bridge qualification remains IN PROGRESS. Native tracking was not restarted when deterministic depth preprocessing was parallelized; six sequential/parallel PNGs matched byte-for-byte. No LiDAR, IMU, GNSS or GT inputs; historical results are preserved.")
  return
 v=json.loads((OUT/'validation.json').read_text());assert v['status']=='PASS_SEGMENTED_FULL_AVAILABLE_RECORDINGS'
 m=v['tracking'];table='\n'.join(f"- {r}: {s['valid_frames']}/{s['frames']} valid camera poses ({s['valid_ratio']:.6f}), {s['map_epochs']} Map Epochs, {s['wall_s']:.3f} s native wall time, {s['peak_RSS_MiB']} MiB native peak RSS." for r,s in m.items())
 conclusion=f"Full available camera-only experiment and segmented replay are validated. RGB durations are {r1['duration_s']:.9f} s / {r3['duration_s']:.9f} s, so Robot1 cannot supply the Stage20 1972.5-second duration. The new demo spans both complete available streams with a 10:1 clock and an explicit shorter-recording end. This is not proof of uninterrupted tracking or a complete global map.\n\n{table}\n\nBridge diagnostic: {v['fusion']['status']}; {v['fusion']['single_pair_passes']} single-pair geometric passes, {len(v['fusion']['verified_epoch_pairs'])} supported epoch-pair bridges. No unrelated reset gauges are glued. See docs/CUMULTI_STAGE24_FULL_RGBD_MAPPING.md, demo/stage24_full_rgbd/README.md and outputs/cumulti_v1/24_rgbd_full_v1/VALIDATION_REPORT.txt. All scientific and presentation limitations remain explicit."
 append('PROJECT_CONTEXT.md','2026-11-10 — Full available camera RGB-D mapping',conclusion)
 append('RESULTS.md','Verified full available RGB-D run (2026-11-10)',conclusion)
 append('EXPERIMENT_LOG.md','2026-11-10 — Full available RGB-D tracking, epoch maps and replay validation', 'Objective: full camera recordings rather than another pilot. Method: independently paced 1000-feature native RGB-D with every original RGB message, measured projected camera depth and unchanged calibration. Dense maps: 1 Hz, stride 8, 0.1 m first-observation voxels; each native gauge remains separate. RGB-only offline BoW proposals and predeclared metric geometric checks condition any epoch-pair fusion; no GT-based selection or tuning.\n\n'+conclusion+'\n\nInputs, source/library hashes and full settings are in run_provenance.json; timestamps and association errors are preserved in sync_pairs.csv. Browser controls, original-frame seeks, future-point exclusion, both 3D panels and cache bounds were tested on the complete output. PLYs, original/native frame sequences and full presentation RGB assets remain server-only with manifests. No historical Stage20/P5/P6 or 12/120-second results were replaced.')
 append('NEXT_STEPS.md','After full available camera RGB-D replay (2026-11-10)','Stop at this checkpoint. Review full-sequence tracking fragmentation and unpaired-depth intervals independently of browser success. Inspect per-epoch maps rather than treating a reset-gauge collection as one consistent map. Any new bridge or graph-fusion method requires its own explicit validation; the bounded RGB-D bridge study does not establish complete global fusion. Do not change the frozen LiDAR/iSAM2 baselines or semantic-mounting-calibration conclusions.\n\n'+conclusion)

if __name__=='__main__':run('--audit-only' in sys.argv)
